package com.autumnharvestc.server.sync;
import com.autumnharvestc.server.store.UserAccount;
import com.autumnharvestc.server.access.AccessRepo;
import com.autumnharvestc.server.collaboration.runtime.*;
import com.autumnharvestc.server.execution.assets.ProjectAssetsService;
import com.autumnharvestc.server.execution.ExecutionDtos.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.ObjectNode;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.jdbc.core.JdbcTemplate;
import java.util.*;
@Service
public class SyncApplicationService {
    private final RuntimeProperties runtimeProperties;private final RuntimeProtocol protocol;private final SyncStorage accounting;private final SyncRepo repo;private final SyncSourceService sources;private final SyncDtos dtos;private final ProjectAssetsService assets;private final CollaborationRuntimeClient core;private final ObjectMapper json;private final TransactionTemplate tx;private final AccessRepo authority;private final JdbcTemplate jdbc;private final SyncHistoryService history;private final SyncCandidateService candidates;private final SyncPolicyService policies;private final com.autumnharvestc.server.execution.agent.AgentService agents;
    public SyncApplicationService(SyncRepo repo,SyncSourceService sources,SyncDtos dtos,ProjectAssetsService assets,CollaborationRuntimeClient core,ObjectMapper json,PlatformTransactionManager transactions,AccessRepo authority,JdbcTemplate jdbc,SyncHistoryService history,SyncCandidateService candidates,SyncPolicyService policies,com.autumnharvestc.server.execution.agent.AgentService agents,SyncStorage accounting,RuntimeProtocol protocol,RuntimeProperties runtimeProperties){this.runtimeProperties=runtimeProperties;this.protocol=protocol;this.accounting=accounting;this.repo=repo;this.sources=sources;this.dtos=dtos;this.assets=assets;this.core=core;this.json=json;this.tx=new TransactionTemplate(transactions);this.authority=authority;this.jdbc=jdbc;this.history=history;this.candidates=candidates;this.policies=policies;this.agents=agents;}
    public JsonNode apply(UserAccount actor,String ws,String project,JsonNode input){return execute(actor,ws,project,input,false);}
    public JsonNode rollback(UserAccount actor,String ws,String project,JsonNode input){return execute(actor,ws,project,input,true);}
    private JsonNode execute(UserAccount actor,String ws,String project,JsonNode input,boolean rollback){
        String kind=rollback?"rollback":"apply";
        String pinOwner=UUID.randomUUID().toString();boolean[] pinned={false};
        long operationDeadline=System.currentTimeMillis()+runtimeProperties.getCallTimeoutMs()+Math.min(runtimeProperties.getCallTimeoutMs(),10000);
        dtos.require(rollback?"rollback":"application",input);long w=Long.parseLong(ws),p=Long.parseLong(project);String intent=input.path("intentId").asText(),sourceId=input.path("sourceId").asText(),digest=dtos.digest(kind,sourceId,input);
        try {
        var fixed=tx.execute(status->{accounting.lock(w,p);authority.lockGate();agents.requireCapability(actor,ws,project,com.autumnharvestc.server.access.Capability.SYNC_APPLY);sources.requireRead(actor,ws,project);var replay=repo.replay(w,p,intent,actor.id(),kind,digest);if(replay.isPresent()){SyncHistoryService.verify(json,"receipt",replay.get());return replay.get();}if(rollback){var snapshot=rollbackInput(actor,ws,project,input);history.pin(w,p,input.path("historyId").asText(),pinOwner,operationDeadline);pinned[0]=true;return snapshot;}requireCurrent(actor,ws,project,input);return repo.candidate(w,p,input.path("candidateId").asText()).orElseThrow(()->SyncRepo.missing("sync_candidate_not_found")).fixed();});
        if(fixed.has("status"))return fixed;
        var policy=tx.execute(status->policies.requireEffective(w,p));
        var resolve=json.createObjectNode();if(!rollback){resolve.set("candidate",fixed.path("candidate"));resolve.set("planInput",fixed.path("planInput"));resolve.set("decisions",input.path("decisions"));}else resolve=(ObjectNode)fixed;
        var payload=json.createObjectNode().put("kind","online-commit");payload.set("input",resolve);
        JsonNode artifacts;try{artifacts=core.call(rollback?"sync-rollback":"sync-resolve",payload,operationDeadline,(int)(policy.path("deploymentLimits").path("maxWireBytes").asLong()-policy.path("deploymentLimits").path("envelopeReserveBytes").asLong()));}catch(CollaborationRuntimeClient.Failure failure){throw SyncDtos.conflict(failure.code());}var plan=artifacts.path("plan");
        if(!rollback&&!plan.path("decisionsDigest").equals(input.path("decisionsDigest")))throw SyncDtos.conflict("SYNC_CANDIDATE_MISMATCH");
        var changes=new ArrayList<AssetChange>();plan.path("writes").forEach(file->changes.add(new AssetChange(file.path("path").asText(),file.path("content").asText())));var deletes=new ArrayList<String>();plan.path("deletions").forEach(file->deletes.add(file.asText()));
        var delta=new AssetDelta("contract-files-v1",plan.path("stamp").path("projectId").asText(),input.path("expectedAssetVersion").asText(),changes,deletes);
        var prepared=tx.execute(status->{accounting.lock(w,p);authority.lockGate();if(!rollback)requireCurrent(actor,ws,project,input);else requireRollbackCurrent(actor,ws,project,input,fixed,pinOwner);return assets.prepareAtomic(actor,ws,project,delta);});var classification=assets.classifyAtomic(actor,prepared);
        return tx.execute(status->{accounting.lock(w,p);authority.lockGate();agents.requireCapability(actor,ws,project,com.autumnharvestc.server.access.Capability.SYNC_APPLY);sources.requireRead(actor,ws,project);var replay=repo.replay(w,p,intent,actor.id(),kind,digest);if(replay.isPresent()){SyncHistoryService.verify(json,"receipt",replay.get());return replay.get();}if(!rollback)requireCurrent(actor,ws,project,input);else requireRollbackCurrent(actor,ws,project,input,fixed,pinOwner);if(!RuntimeProtocol.digestJson(policy).equals(RuntimeProtocol.digestJson(policies.requireEffective(w,p))))throw SyncDtos.conflict("sync_policy_changed");var after=assets.commitAtomic(actor,ws,project,delta,classification);
            var state=repo.sourceState(w,p,sourceId);String mappingRevision=rollback?state.mappingRevision():SyncDtos.next(state.mappingRevision()),baselineRevision=rollback?state.baselineRevision():SyncDtos.next(state.baselineRevision());var mapping=(ObjectNode)plan.path("mapping").deepCopy();mapping.put("revision",mappingRevision);String baseline=artifacts.path("baseline").path("text").asText();if(!rollback)jdbc.update("UPDATE sync_sources SET mapping_revision=?,baseline_revision=?,mapping_json=?,baseline_json=?,baseline_ref_json=?,baseline_bytes=? WHERE workspace_id=? AND project_id=? AND id=?",mappingRevision,baselineRevision,mapping.toString(),baseline,artifacts.path("baseline").path("reference").toString(),(long)baseline.getBytes(java.nio.charset.StandardCharsets.UTF_8).length,w,p,sourceId);
            var afterStamp=(ObjectNode)plan.path("stamp").deepCopy();afterStamp.put("assetVersion",after.version()).put("definitionRevision",plan.path("after").path("definitionRevision").asText()).put("mappingRevision",mappingRevision).put("baselineRevision",baselineRevision);
            String historyId=UUID.randomUUID().toString();long now=System.currentTimeMillis();var actorView=json.createObjectNode().put("id",String.valueOf(actor.id())).put("name",actor.displayName()==null?actor.username():actor.displayName());
            var entry=json.createObjectNode().put("formatVersion",1).put("id",historyId).put("sourceId",sourceId).put("projectId",after.contractProjectId()).put("intentId",intent).put("operationKind",kind).put("createdAtMs",now);entry.set("actor",actorView);entry.set("beforeStamp",plan.path("stamp"));entry.set("afterStamp",afterStamp);entry.set("upstream",rollback?fixed.path("history").path("upstream"):fixed.path("candidate").path("upstream"));entry.set("before",plan.path("before"));entry.set("after",plan.path("after"));var rollbackRefs=entry.putObject("rollback");rollbackRefs.set("beforeContent",artifacts.path("before").path("reference"));rollbackRefs.set("afterContent",artifacts.path("after").path("reference"));SyncHistoryService.seal(json,"history",entry);history.save(w,p,entry,artifacts);accounting.changed(w,p);
            var receipt=json.createObjectNode().put("formatVersion",1).put("operationId",UUID.randomUUID().toString()).put("intentId",intent).put("kind",kind).put("status","committed").put("historyId",historyId).put("sourceId",sourceId).put("projectId",after.contractProjectId()).put("completedAtMs",now);receipt.set("afterStamp",afterStamp);receipt.set("actor",actorView);SyncHistoryService.seal(json,"receipt",receipt);repo.operation(w,p,intent,actor.id(),kind,digest,receipt);return receipt;
        });
        } finally {if(pinned[0])tx.executeWithoutResult(status->{accounting.lock(w,p);if(!jdbc.queryForList("SELECT id FROM projects WHERE workspace_id=? AND id=? FOR UPDATE",w,p).isEmpty())history.unpin(w,p,input.path("historyId").asText(),pinOwner);});}
    }
    private JsonNode rollbackInput(UserAccount actor,String ws,String project,JsonNode input){
        long w=Long.parseLong(ws),p=Long.parseLong(project);var stored=history.stored(w,p,input.path("historyId").asText());var state=repo.sourceState(w,p,input.path("sourceId").asText());if(!stored.entry().path("sourceId").equals(input.path("sourceId"))||!state.source().path("revision").equals(input.path("expectedSourceRevision")))throw SyncDtos.conflict("SYNC_ROLLBACK_STAMP_MISMATCH");var current=assets.get(actor,ws,project);var stamp=(ObjectNode)stored.entry().path("afterStamp").deepCopy();stamp.put("assetVersion",current.version()).put("sourceRevision",state.source().path("revision").asText()).put("mappingRevision",state.mappingRevision()).put("baselineRevision",state.baselineRevision()).put("authorizationGeneration",String.valueOf(authority.projectRevision(w,p))).put("coreBuildId",protocol.coreBuildIdentity());
        var result=json.createObjectNode();result.set("history",stored.entry());result.set("beforeFiles",stored.before());result.set("afterFiles",stored.after());result.set("currentStamp",stamp);var files=result.putArray("currentFiles");current.files().forEach(file->files.addObject().put("path",file.path()).put("content",file.content()));result.set("mapping",state.mapping());result.set("baselineFiles",state.baseline());var others=result.putArray("otherSourceMappings");for(var source:repo.sources(w,p))if(!source.path("id").equals(input.path("sourceId"))){var mapping=repo.sourceState(w,p,source.path("id").asText()).mapping();if(mapping!=null)others.add(mapping);}var budget=result.putObject("budget");var policy=policies.requireEffective(w,p).path("policy");for(String field:List.of("maxCompareInputBytes","maxCompareOutputBytes"))budget.set(field,policy.path(field));return result;
    }
    private void requireRollbackCurrent(UserAccount actor,String ws,String project,JsonNode input,JsonNode fixed,String pinOwner){
        agents.requireCapability(actor,ws,project,com.autumnharvestc.server.access.Capability.SYNC_APPLY);long w=Long.parseLong(ws),p=Long.parseLong(project);history.requirePin(w,p,input.path("historyId").asText(),pinOwner);var state=repo.sourceState(w,p,input.path("sourceId").asText());var stamp=fixed.path("currentStamp");
        if(!state.source().path("revision").equals(stamp.path("sourceRevision"))||!state.mappingRevision().equals(stamp.path("mappingRevision").asText())||!state.baselineRevision().equals(stamp.path("baselineRevision").asText())||!String.valueOf(authority.projectRevision(w,p)).equals(stamp.path("authorizationGeneration").asText())||!protocol.coreBuildIdentity().equals(stamp.path("coreBuildId").asText())||!assets.get(actor,ws,project).version().equals(stamp.path("assetVersion").asText()))throw SyncDtos.conflict("SYNC_ROLLBACK_STAMP_MISMATCH");
        var stored=history.stored(w,p,input.path("historyId").asText());if(!RuntimeProtocol.digestJson(stored.entry()).equals(RuntimeProtocol.digestJson(fixed.path("history")))||!RuntimeProtocol.digestJson(stored.before()).equals(RuntimeProtocol.digestJson(fixed.path("beforeFiles")))||!RuntimeProtocol.digestJson(stored.after()).equals(RuntimeProtocol.digestJson(fixed.path("afterFiles"))))throw SyncDtos.conflict("SYNC_ROLLBACK_HISTORY_MISMATCH");
    }
    private void requireCurrent(UserAccount actor,String ws,String project,JsonNode input){
        agents.requireCapability(actor,ws,project,com.autumnharvestc.server.access.Capability.SYNC_APPLY);
        var view=candidates.read(actor,ws,project,input.path("candidateId").asText());if(!view.path("applicable").asBoolean())throw SyncDtos.conflict(view.path("reasonCode").asText());var candidate=view.path("candidate");
        if(!candidate.path("sourceId").equals(input.path("sourceId"))||!candidate.path("candidateDigest").equals(input.path("candidateDigest"))||!candidate.path("stamp").path("assetVersion").equals(input.path("expectedAssetVersion"))||!candidate.path("stamp").path("sourceRevision").equals(input.path("expectedSourceRevision")))throw SyncDtos.conflict("SYNC_CANDIDATE_MISMATCH");
    }
}
